<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><title>Bon de transfert #{{ $transfer->id }}</title><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:11px;margin:30px}.header{display:table;width:100%;border-bottom:3px solid #d97706;padding-bottom:15px}.left,.right{display:table-cell;vertical-align:top}.right{text-align:right}.logo{max-height:70px;max-width:240px}.title{font-size:24px;font-weight:bold;color:#d97706}.meta{width:100%;margin:22px 0;border-collapse:collapse}.meta td{width:50%;padding:8px;border:1px solid #e2e8f0}.label{font-size:9px;text-transform:uppercase;color:#64748b}.value{font-size:12px;font-weight:bold;margin-top:3px}table.lines{width:100%;border-collapse:collapse}.lines th{background:#f1f5f9;padding:9px;text-align:left}.lines td{padding:10px 9px;border-bottom:1px solid #e2e8f0}.rightText{text-align:right}.ref{font-size:9px;color:#64748b;font-family:monospace}.note{font-size:9px;color:#64748b;font-style:italic}.footer{margin-top:35px;border-top:1px solid #e2e8f0;padding-top:10px;color:#64748b;font-size:9px}</style></head><body><div class="header"><div class="left">@if($logoB64)<img src="{{ $logoB64 }}" class="logo">@else <strong>{{ $settings['company_name'] ?? config('app.name') }}</strong>@endif</div><div class="right"><div class="label">Bon de transfert</div><div class="title">{{ $transfer->transfer_number ?? ('BT-'.str_pad($transfer->id,6,'0',STR_PAD_LEFT)) }}</div><div>{{ $transfer->transferred_at->format('d/m/Y') }}</div></div></div><table class="meta"><tr><td><div class="label">Chantier destination</div><div class="value">{{ $transfer->project?->code }} — {{ $transfer->project?->name }}</div></td><td><div class="label">Bon de commande source</div><div class="value">{{ $transfer->reception?->purchaseOrder?->order_number ?? $transfer->reception?->purchaseOrder?->title }}</div></td></tr><tr><td><div class="label">Référence sortie</div><div class="value">{{ $transfer->reference ?? '—' }}</div></td><td><div class="label">Effectué par</div><div class="value">{{ $transfer->actor?->name ?? '—' }}</div></td></tr></table><table class="lines"><thead><tr><th>Article</th><th class="rightText">Quantité transférée</th></tr></thead><tbody>@foreach($transfer->lines as $line)<tr><td><strong>{{ $line->receptionLine?->orderLine?->article?->name ?? 'Article' }}</strong>@if($line->receptionLine?->orderLine?->article?->reference)<div class="ref">{{ $line->receptionLine->orderLine->article->reference }}</div>@endif @if($line->receptionLine?->orderLine?->note)<div class="note">{{ $line->receptionLine->orderLine->note }}</div>@endif</td><td class="rightText"><strong>{{ number_format($line->quantity_transferred,2,',',' ') }}</strong> {{ $line->receptionLine?->orderLine?->article?->unit }}</td></tr>@endforeach</tbody></table>@if($transfer->notes)<p><strong>Notes :</strong> {{ $transfer->notes }}</p>@endif
